   </div>
   <div class="footer"><span>PROCEDURAL DUNGEON · TURN-BASED COMBAT</span><span>THE DEEP REMEMBERS EVERY STEP</span></div>
 </main>
 <script>
+'use strict';
+const W=25,H=17,T=32,canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),mini=document.querySelector('#map'),mctx=mini.getContext('2d');
+const ui={overlay:document.querySelector('#overlay'),title:document.querySelector('#overlayTitle'),text:document.querySelector('#overlayText'),start:document.querySelector('#startButton'),floor:document.querySelector('#floorText'),objective:document.querySelector('#objective'),hp:document.querySelector('#hpText'),hpBar:document.querySelector('#hpBar'),xp:document.querySelector('#xpText'),xpBar:document.querySelector('#xpBar'),level:document.querySelector('#levelText'),atk:document.querySelector('#atkText'),potions:document.querySelector('#potionText'),kills:document.querySelector('#killText'),depth:document.querySelector('#depthText'),run:document.querySelector('#runTag'),log:document.querySelector('#log')};
+const floorNames=['THE ROOT CELLAR','MOSSBOUND GALLERY','THE SUNKEN ARCHIVE','WIDOW’S CATACOMBS','THE HOLLOW THRONE'];
+let game={started:false,over:false,floor:1,map:[],seen:[],rooms:[],player:null,enemies:[],items:[],stairs:null,logs:[],kills:0,turn:0,seed:1};
+function rand(n){game.seed=(game.seed*1664525+1013904223)>>>0;return game.seed%n}function choose(a){return a[rand(a.length)]}function inside(x,y){return x>=0&&y>=0&&x<W&&y<H}function walk(x,y){return inside(x,y)&&game.map[y][x]===0}
+function roomContains(room,x,y){return x>=room.x&&x<room.x+room.w&&y>=room.y&&y<room.y+room.h}
+function carveRoom(r){for(let y=r.y;y<r.y+r.h;y++)for(let x=r.x;x<r.x+r.w;x++)game.map[y][x]=0}
+function corridor(x1,y1,x2,y2){if(rand(2)){for(let x=Math.min(x1,x2);x<=Math.max(x1,x2);x++)game.map[y1][x]=0;for(let y=Math.min(y1,y2);y<=Math.max(y1,y2);y++)game.map[y][x2]=0}else{for(let y=Math.min(y1,y2);y<=Math.max(y1,y2);y++)game.map[y][x1]=0;for(let x=Math.min(x1,x2);x<=Math.max(x1,x2);x++)game.map[y2][x]=0}}
+function generateFloor(){
+ game.map=Array.from({length:H},()=>Array(W).fill(1));game.seen=Array.from({length:H},()=>Array(W).fill(false));game.rooms=[];
+ for(let tries=0;tries<170&&game.rooms.length<8;tries++){let r={x:1+rand(W-9),y:1+rand(H-7),w:4+rand(5),h:4+rand(4)};if(r.x+r.w>=W-1||r.y+r.h>=H-1)continue;if(game.rooms.some(q=>r.x<q.x+q.w+1&&r.x+r.w+1>q.x&&r.y<q.y+q.h+1&&r.y+r.h+1>q.y))continue;carveRoom(r);if(game.rooms.length){let p=game.rooms[game.rooms.length-1],a={x:p.x+(p.w>>1),y:p.y+(p.h>>1)},b={x:r.x+(r.w>>1),y:r.y+(r.h>>1)};corridor(a.x,a.y,b.x,b.y)}game.rooms.push(r)}
+ if(game.rooms.length<2){game.map[4][4]=0;game.map[4][5]=0;game.map[4][6]=0;game.map[5][6]=0;game.rooms=[{x:2,y:2,w:5,h:5},{x:6,y:4,w:5,h:5}]}
+ let first=game.rooms[0],last=game.rooms[game.rooms.length-1];game.player={x:first.x+(first.w>>1),y:first.y+(first.h>>1),hp:24,maxHp:24,level:1,xp:0,need:4,attack:5,potions:2};game.stairs={x:last.x+(last.w>>1),y:last.y+(last.h>>1)};
+ game.enemies=[];game.items=[];const used=new Set([`${game.player.x},${game.player.y}`,`${game.stairs.x},${game.stairs.y}`]);
+ function spot(room,minDist=0){for(let i=0;i<80;i++){let x=room.x+rand(room.w),y=room.y+rand(room.h),key=`${x},${y}`;if(!used.has(key)&&Math.abs(x-game.player.x)+Math.abs(y-game.player.y)>=minDist){used.add(key);return{x,y}}}return null}
+ let kinds=game.floor===5?['warden']:['rat','fungus','shade','skeleton'];let count=game.floor===5?1:Math.min(4+game.floor,8);
+ for(let i=0;i<count;i++){let room=game.rooms[1+rand(game.rooms.length-1)]||last,p=spot(room,4);if(!p)continue;let type=game.floor===5?'warden':choose(kinds),base={rat:[7,2,1,'Rat'],fungus:[10,3,2,'Mushroom'],shade:[9,4,3,'Gloam'],skeleton:[12,5,4,'Boneguard'],warden:[42,8,7,'The Hollow Warden']}[type];game.enemies.push({...p,type,hp:base[0]+Math.max(0,game.floor-1)*2,maxHp:base[0]+Math.max(0,game.floor-1)*2,attack:base[1]+Math.floor((game.floor-1)/2),xp:base[2],name:base[3],wake:false})}
+ if(game.floor<5){let candidates=game.rooms.slice(1,-1);if(!candidates.length)candidates=[last];let r=choose(candidates),p=spot(r,0);if(p)game.items.push({...p,type:'potion'})}else game.stairs=null;
+ game.turn=0;reveal();updateUI();draw();
+}
+function reveal(){let p=game.player,r=7;for(let y=Math.max(0,p.y-r);y<=Math.min(H-1,p.y+r);y++)for(let x=Math.max(0,p.x-r);x<=Math.min(W-1,p.x+r);x++){let dx=x-p.x,dy=y-p.y;if(dx*dx+dy*dy<=r*r)game.seen[y][x]=true}}
+function visible(x,y){let p=game.player,dx=x-p.x,dy=y-p.y;return dx*dx+dy*dy<=49}
+function message(text){game.logs.unshift(text);game.logs=game.logs.slice(0,5);ui.log.innerHTML=game.logs.map((s,i)=>`<p style="opacity:${1-i*.14}">${s}</p>`).join('')}
+function start(){game.seed=(Date.now()^Math.floor(Math.random()*1e9))>>>0;game.floor=1;game.kills=0;game.logs=[];game.over=false;game.started=true;ui.run.textContent='RUN '+String(rand(900)+100)+' · IN PROGRESS';message('You descend, lantern held high.');generateFloor();ui.overlay.classList.add('hidden')}

