function draw(){
 ctx.fillStyle='#080b08';ctx.fillRect(0,0,canvas.width,canvas.height);if(!game.map.length){drawMini();return}
 for(let y=0;y<H;y++)for(let x=0;x<W;x++){let px=x*T,py=y*T;if(!game.seen[y][x])continue;let isFloor=game.map[y][x]===0,lit=visible(x,y);ctx.fillStyle=isFloor?(lit?'#252a20':'#151914'):(lit?'#30352a':'#1b201a');ctx.fillRect(px,py,T,T);
 if(isFloor){let n=(x*17+y*31)%9;if(n===0||n===4){ctx.fillStyle=lit?'#32372a':'#20251d';ctx.fillRect(px+5+(n*3)%17,py+7+(n*5)%16,2,2)}if((x+y*3)%17===0){ctx.strokeStyle=lit?'#34392b':'#1d221b';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(px+4,py+26);ctx.lineTo(px+11,py+22);ctx.lineTo(px+18,py+26);ctx.stroke()}}
 else {ctx.fillStyle=lit?'#3a4032':'#242920';ctx.fillRect(px+2,py+2,T-4,4);ctx.fillRect(px+2,py+2,4,T-4);ctx.fillStyle=lit?'#292e24':'#1b201a';ctx.fillRect(px+T-5,py+7,3,T-10);ctx.fillRect(px+7,py+T-5,T-10,3);if((x*7+y*13)%5===0){ctx.fillStyle='#555a43';ctx.fillRect(px+8,py+12,1,1);ctx.fillRect(px+21,py+20,2,1)}}
 }
 if(game.stairs&&game.seen[game.stairs.y]?.[game.stairs.x]){let{x,y}=game.stairs,px=x*T,py=y*T;ctx.fillStyle='#11150f';ctx.beginPath();ctx.ellipse(px+16,py+18,11,8,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#bd9a51';ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(px+9+i*2,py+14+i*4);ctx.lineTo(px+22,py+14+i*4);ctx.stroke()}ctx.fillStyle='#e3c36f';ctx.font='10px sans-serif';ctx.fillText('↓',px+12,py+12)}
 for(let item of game.items)if(visible(item.x,item.y)){let px=item.x*T,py=item.y*T;ctx.fillStyle='#dfa75a';ctx.beginPath();ctx.arc(px+16,py+16,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f6d891';ctx.fillRect(px+13,py+8,6,3);ctx.fillStyle='#793f31';ctx.fillRect(px+14,py+12,4,8);ctx.fillStyle='#fff0c1';ctx.font='bold 11px sans-serif';ctx.fillText('+',px+12,py+20)}
 for(let e of game.enemies){if(!visible(e.x,e.y))continue;drawEnemy(e)}drawPlayer();
 let glow=ctx.createRadialGradient(game.player.x*T+16,game.player.y*T+16,16,game.player.x*T+16,game.player.y*T+16,245);glow.addColorStop(0,'#e6bd4b0d');glow.addColorStop(1,'#00000022');ctx.fillStyle=glow;ctx.fillRect(0,0,canvas.width,canvas.height);drawMini();
}
function drawPlayer(){let x=game.player.x*T,y=game.player.y*T;ctx.save();ctx.translate(x,y);ctx.fillStyle='#10130e';ctx.beginPath();ctx.ellipse(16,26,10,4,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#536047';ctx.beginPath();ctx.moveTo(6,25);ctx.lineTo(9,14);ctx.lineTo(16,10);ctx.lineTo(23,14);ctx.lineTo(27,25);ctx.closePath();ctx.fill();ctx.fillStyle='#d9d3ba';ctx.beginPath();ctx.arc(16,11,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#292a20';ctx.fillRect(12,10,9,3);ctx.fillStyle='#e5c573';ctx.fillRect(20,18,3,7);ctx.fillStyle='#fff0ad';ctx.beginPath();ctx.arc(24,18,3,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawEnemy(e){let x=e.x*T,y=e.y*T;ctx.save();ctx.translate(x,y);ctx.fillStyle='#10130e';ctx.beginPath();ctx.ellipse(16,26,10,4,0,0,Math.PI*2);ctx.fill();if(e.type==='rat'){ctx.fillStyle='#a18b72';ctx.beginPath();ctx.ellipse(15,19,10,6,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(23,16,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e87559';ctx.fillRect(24,15,2,2);ctx.strokeStyle='#ab8770';ctx.beginPath();ctx.moveTo(7,20);ctx.quadraticCurveTo(0,20,3,26);ctx.stroke()}else if(e.type==='fungus'){ctx.fillStyle='#536847';ctx.fillRect(10,16,12,10);ctx.fillStyle='#a76c55';ctx.beginPath();ctx.ellipse(16,16,12,7,0,Math.PI,0);ctx.fill();ctx.fillStyle='#ede2c5';ctx.fillRect(12,17,2,2);ctx.fillRect(19,17,2,2)}else if(e.type==='shade'){ctx.fillStyle='#727f9a';ctx.globalAlpha=.85;ctx.beginPath();ctx.moveTo(5,25);ctx.quadraticCurveTo(7,10,16,8);ctx.quadraticCurveTo(26,11,27,25);ctx.lineTo(22,21);ctx.lineTo(18,26);ctx.lineTo(13,22);ctx.closePath();ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#d5d9bb';ctx.fillRect(12,15,3,2);ctx.fillRect(19,15,3,2)}else if(e.type==='warden'){ctx.fillStyle='#51443c';ctx.beginPath();ctx.moveTo(4,26);ctx.lineTo(6,12);ctx.lineTo(10,5);ctx.lineTo(13,11);ctx.lineTo(19,4);ctx.lineTo(23,12);ctx.lineTo(28,26);ctx.closePath();ctx.fill();ctx.fillStyle='#e4a95c';ctx.fillRect(10,14,4,3);ctx.fillRect(19,14,4,3);ctx.fillStyle='#b84f3b';ctx.fillRect(9,24,14,3)}else{ctx.fillStyle='#c4b995';ctx.fillRect(9,12,14,14);ctx.fillStyle='#e0d7b6';ctx.fillRect(10,7,12,9);ctx.fillStyle='#302f27';ctx.fillRect(12,11,3,3);ctx.fillRect(18,11,3,3);ctx.strokeStyle='#d5c795';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(8,15);ctx.lineTo(5,22);ctx.moveTo(24,15);ctx.lineTo(27,22);ctx.stroke()}
 if(e.hp<e.maxHp){ctx.fillStyle='#111';ctx.fillRect(5,2,22,3);ctx.fillStyle='#d26351';ctx.fillRect(6,3,20*Math.max(0,e.hp/e.maxHp),1.5)}ctx.restore()}
function drawMini(){mctx.fillStyle='#0d100d';mctx.fillRect(0,0,mini.width,mini.height);if(!game.map.length)return;let s=Math.min(mini.width/W,mini.height/H),ox=(mini.width-W*s)/2,oy=(mini.height-H*s)/2;for(let y=0;y<H;y++)for(let x=0;x<W;x++)if(game.seen[y][x]){mctx.fillStyle=game.map[y][x]===0?'#687057':'#343b30';mctx.fillRect(ox+x*s,oy+y*s,Math.ceil(s),Math.ceil(s))}for(const e of game.enemies)if(visible(e.x,e.y)){mctx.fillStyle=e.type==='warden'?'#ed715d':'#d48264';mctx.fillRect(ox+e.x*s,oy+e.y*s,Math.max(2,s),Math.max(2,s))}if(game.stairs&&game.seen[game.stairs.y]?.[game.stairs.x]){mctx.fillStyle='#e5bd63';mctx.fillRect(ox+game.stairs.x*s,oy+game.stairs.y*s,Math.max(2,s),Math.max(2,s))}if(game.player){mctx.fillStyle='#fff1b1';mctx.fillRect(ox+game.player.x*s,oy+game.player.y*s,Math.max(2,s),Math.max(2,s))}}

